function downloadCSV(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function teacherOverview(){const view=$('view');view.append(node('h2','','📊 Sınıf analitiği'),node('p','muted','Üç örnek öğrenciye ait aynı tarayıcıdaki verilerin özeti. Çevrim içi senkronizasyon yoktur.'));const records=roster.map(st=>({st,d:studentData(st.id)}));const cards=node('div','stat-grid');const sum=(fn)=>records.reduce((n,x)=>n+fn(x.d),0);[[records.length,'Öğrenci'],[sum(d=>d.completed.length),'Tamamlanan ders'],[sum(d=>d.questions),'Soru denemesi'],[duration(sum(d=>d.seconds)),'Toplam çalışma'],[sum(d=>d.assignments.length),'Atanan ödev'],[sum(d=>d.assignments.filter(a=>d.completed.includes(a.lesson)).length),'Tamamlanan ödev']].forEach(([v,l])=>{const c=node('div','stat');c.append(node('strong','',String(v)),node('span','',l));cards.append(c)});view.append(cards);const table=node('div','report-table');const head=node('div','report-row report-head');['Öğrenci','Ders','Soru','Başarı','Çalışma','Ödev'].forEach(x=>head.append(node('span','',x)));table.append(head);records.forEach(({st,d})=>{const row=node('div','report-row');[st.name,d.completed.length+'/48',d.questions,d.questions?Math.round(100*d.correct/d.questions)+'%':'—',duration(d.seconds),d.assignments.filter(a=>d.completed.includes(a.lesson)).length+'/'+d.assignments.length].forEach(v=>row.append(node('span','',String(v))));row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label',st.name+' dosyasını aç');row.onclick=()=>{teacherStudent=st.id;showSection('student-detail')};row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click()}};table.append(row)});view.append(table);view.append(button('⬇ CSV raporu indir',()=>downloadCSV('chess-academy-class-report.csv',[['Öğrenci','Kullanıcı','Ders','Soru','Doğru','Saniye','Ödev','Tamamlanan'],...records.map(({st,d})=>[st.name,st.user,d.completed.length,d.questions,d.correct,d.seconds,d.assignments.length,d.assignments.filter(a=>d.completed.includes(a.lesson)).length])]),'btn gold'));view.append(node('h3','','Öğretmen için takip önerileri'));records.forEach(({st,d})=>{const completion=d.assignments.filter(a=>d.completed.includes(a.lesson)).length;const pending=d.assignments.length-completion;const advice=d.questions>=10&&d.correct/d.questions<.65?'Yanlış cevapları gözden geçirip temel taktik tekrarına yönlendirin.':pending>0?'Bekleyen '+pending+' ödevi birlikte gözden geçirin.':d.completed.length===0?'İlk dersi ve başlangıç seviye çalışmasını atayın.':'Düzenli çalışma hedefi belirleyin.';view.append(node('p','muted',st.name+': '+advice))})}
